  5	
  6	\section{Sheaves}
  7	
  8	\begin{definition}[Presheaf and sheaf]
  9	\label{def:II-1-presheaf}
 10	\source{hartshorne-algebraic-geometry:II.1}
 11	\lean{Hartshorne.Presheaf, Hartshorne.Sheaf, Hartshorne.IsSheaf}
 12	\leanok
 13	A presheaf $\mathcal F$ on $X$ assigns an object $\mathcal F(U)$ to every open $U$ and restriction maps
 14	$\mathcal F(U)\to\mathcal F(V)$ for $V\subset U$, functorially, with $\mathcal F(\varnothing)=0$.
 15	It is a sheaf when sections that agree locally glue uniquely. The definitions apply to sets,
 16	abelian groups, rings, and modules.
 17	More explicitly, if $\{U_i\}$ covers $U$, then restriction to the $U_i$ is injective, and every
 18	family $s_i\in\mathcal F(U_i)$ satisfying
 19	$s_i|_{U_i\cap U_j}=s_j|_{U_i\cap U_j}$ comes from a unique $s\in\mathcal F(U)$.
 20	\end{definition}
 21	
 22	\begin{definition}[Stalks and morphisms]
 23	\label{def:II-1-stalk}
 24	\source{hartshorne-algebraic-geometry:II.1}
 25	\lean{Hartshorne.Stalk, Hartshorne.germ, Hartshorne.stalkMap, Hartshorne.germ_restrict}
 26	\leanok
 27	The stalk is $\mathcal F_x=\varinjlim_{x\in U}\mathcal F(U)$. A morphism is a compatible family
 28	of maps on opens and induces maps on stalks.  A germ is represented by a pair $(U,s)$ with $x\in U$;
 29	$(U,s)$ and $(V,t)$ define the same germ exactly when $s$ and $t$ agree on some neighborhood of $x$
 30	contained in $U\cap V$.
 31	\uses{def:II-1-presheaf}
 32	\end{definition}
 33	
 34	\begin{proposition}[Sheaf isomorphisms are stalkwise]
 35	\label{prop:II-1-1}
 36	\source{hartshorne-algebraic-geometry:II.1.1}
 37	\dcref{II.1.1}
 38	\lean{Hartshorne.sheaf_iso_iff_stalkMap_iso}
 39	\leanok
 40	A morphism of sheaves is an isomorphism if and only if it induces an isomorphism on every stalk.
 41	\uses{def:II-1-presheaf,def:II-1-stalk}
 42	\end{proposition}
 43	\begin{proof}
 44	The forward implication is immediate. If all stalk maps are injective, a section whose germs vanish
 45	has a cover on which it vanishes, hence is zero. If all are surjective, lift the germ of a target
 46	section near each point; after shrinking, the lifts agree on overlaps by injectivity, and the sheaf
 47	axiom glues them. The glued lift maps to the target section.
 48	\end{proof}
 49	
 50	
 51	\begin{proposition}[Sheafification]
 52	\label{prop:II-1-2}
 53	\source{hartshorne-algebraic-geometry:II.1.2}
 54	\dcref{II.1.2}
 55	\lean{Hartshorne.sheafification, Hartshorne.sheafification_condition,
 56	Hartshorne.sheafification_stalkIso, Hartshorne.categoricalSheafification,
 57	Hartshorne.categoricalSheafificationUnit, Hartshorne.categoricalSheafificationLift,
 58	Hartshorne.categoricalSheafificationUnit_lift,
 59	Hartshorne.categoricalSheafificationLift_unique,
 60	Hartshorne.categoricalSheafificationUnit_stalk_isIso}
 61	\leanok
 62	Every presheaf $\mathcal F$ admits a sheafification $\mathcal F^a$ and a universal map
 63	$\mathcal F\to\mathcal F^a$; it is unique up to unique isomorphism and has the same stalks as
 64	$\mathcal F$.
 65	\uses{def:II-1-presheaf,def:II-1-stalk}
 66	\end{proposition}
 67	\begin{proof}
 68	Let $\mathcal F^a(U)$ be the functions assigning to each $x\in U$ a germ in $\mathcal F_x$ which,
 69	locally at every $x$, is represented by a section of $\mathcal F$. These functions form a sheaf under
 70	restriction; the germ map is universal because any map to a sheaf is determined locally.
 71	\end{proof}
 72	
 73	\begin{definition}[Direct and inverse image]
 74	\label{def:II-1-direct-inverse}
 75	\source{hartshorne-algebraic-geometry:II.1}
 76	\lean{Hartshorne.directImage, Hartshorne.presheafDirectImage,
 77	Hartshorne.presheafInverseImage, Hartshorne.sheafInverseImage,
 78	Hartshorne.sheafInverseImageDirectImageAdjunction,
 79	Hartshorne.directImage_presheaf_isSheaf}
 80	\leanok
 81	For a continuous $f:X\to Y$, define $(f_*\mathcal F)(V)=\mathcal F(f^{-1}V)$. The inverse image
 82	$f^{-1}\mathcal G$ is the sheafification of $U\mapsto\varinjlim_{f(U)\subset V}\mathcal G(V)$.
 83	Restriction to a subspace is inverse image under its inclusion.
 84	\uses{def:II-1-presheaf,prop:II-1-2}
 85	\end{definition}
 86	
 87	For a morphism $\varphi:\mathcal F\to\mathcal G$ of presheaves, define the presheaf kernel,
 88	cokernel, and image by
 89	\[
 90	U\longmapsto\ker\varphi(U),\qquad U\longmapsto\operatorname{coker}\varphi(U),
 91	\qquad U\longmapsto\operatorname{im}\varphi(U).
 92	\]
 93	The kernel presheaf of a morphism of sheaves is a sheaf; in general the presheaf cokernel and image
 94	must be sheafified.  Thus kernels are computed sectionwise, while cokernels and images in the sheaf
 95	category are the associated sheaves of the sectionwise constructions.
 96	
 97	\begin{definition}[Subsheaves, exactness, and quotients]
 98	\label{def:II-1-subsheaf-exact}
 99	\source{hartshorne-algebraic-geometry:II.1}
100	A subsheaf $\mathcal F'\subseteq\mathcal F$ is a sheaf whose sections are subgroups of the
101	sections of $\mathcal F$ and whose restrictions are induced.  The kernel of a sheaf morphism is its
102	sectionwise kernel, the image is the sheaf associated to its sectionwise image, and a morphism is
103	injective or surjective according as its kernel is zero or its image is the target.  A sequence is
104	exact when the image at every term equals the kernel at that term.  The quotient $\mathcal F/\mathcal F'$
105	is the sheaf associated to $U\mapsto\mathcal F(U)/\mathcal F'(U)$, with stalks
106	$(\mathcal F/\mathcal F')_x=\mathcal F_x/\mathcal F'_x$.
107	\uses{def:II-1-presheaf,def:II-1-stalk,prop:II-1-2}
108	\end{definition}
